import { quote, type Customer, type Item, type QuoteResult } from "./premium.js";
import { claim, type ClaimResult, type Damage } from "./claim.js";

export type { ClaimResult, Customer, Damage, Item, QuoteResult };

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult = QuoteResult | ClaimResult;

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  let contractsSoFar = 0;
  const results = scenario.steps.map((step): StepResult => {
    if (step.op === "claim") {
      const policyStep = scenario.steps[step.policy];
      return claim(policyStep.op === "quote" ? policyStep.items : [], step.incident.damages);
    }
    const result = quote(step.items, { customer: scenario.customer, isFollowUpContract: contractsSoFar > 0 });
    contractsSoFar++;
    return result;
  });
  return { results };
}
/** MHPCO premium tariff: prices one contract's items for a customer. */
import { COMPONENT_BLOCK_BASE_PREMIUM, COMPONENT_BLOCK_SIZE, COMPONENT_PRICE, MAIN_ITEM_PRICES, isComponent } from "./priceList.js";

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteResult {
  premium: number;
}

const PROCESSING_FEE = 5;
const HUNDRED_PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const HIGH_ENCHANTMENT_LEVEL = 5;
const LOYALTY_DISCOUNT_PERCENT = 20;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / HUNDRED_PERCENT;
}

/** Premiums are rounded up to whole G, in the MHPCO's favor. */
function roundPremiumInMhpcoFavor(premium: number): number {
  return Math.ceil(premium);
}

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  return counts;
}

function basePremiumOfAlikeComponents(count: number): number {
  return count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_BASE_PREMIUM : count * COMPONENT_PRICE.basePremium;
}

function basePremiumOfAlike(type: string, count: number): number {
  if (isComponent(type)) return basePremiumOfAlikeComponents(count);
  return count * MAIN_ITEM_PRICES[type].basePremium;
}

function policyBasePremiumOf(items: Item[]): number {
  let sum = 0;
  for (const [type, count] of countByType(items)) sum += basePremiumOfAlike(type, count);
  return sum;
}

interface ItemRiskSurcharge {
  appliesTo: (item: Item) => boolean;
  percent: number;
}

/** Item-specific modifiers: each applies to the base premium of the affected item only. */
const ITEM_RISK_SURCHARGES: ItemRiskSurcharge[] = [
  { appliesTo: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
  { appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
];

function itemRiskSurchargesOf(items: Item[]): number {
  let sum = 0;
  for (const item of items)
    for (const surcharge of ITEM_RISK_SURCHARGES)
      if (surcharge.appliesTo(item)) sum += percentOf(MAIN_ITEM_PRICES[item.type].basePremium, surcharge.percent);
  return sum;
}

function isLongStandingCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

export interface ContractContext {
  customer: Customer;
  isFollowUpContract: boolean;
}

interface PolicyModifier {
  appliesTo: (contract: ContractContext) => boolean;
  /** Positive for a surcharge, negative for a discount. */
  percent: number;
}

/** Policy-wide modifiers: each applies to the base premium of the whole policy. */
const POLICY_MODIFIERS: PolicyModifier[] = [
  { appliesTo: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
  { appliesTo: (contract) => isLongStandingCustomer(contract.customer), percent: -LOYALTY_DISCOUNT_PERCENT },
  { appliesTo: (contract) => contract.isFollowUpContract, percent: -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT },
];

function policyModifiersOf(policyBasePremium: number, contract: ContractContext): number {
  let sum = 0;
  for (const modifier of POLICY_MODIFIERS)
    if (modifier.appliesTo(contract)) sum += percentOf(policyBasePremium, modifier.percent);
  return sum;
}

export function quote(items: Item[], contract: ContractContext): QuoteResult {
  const policyBasePremium = policyBasePremiumOf(items);
  const premium =
    policyBasePremium + itemRiskSurchargesOf(items) + policyModifiersOf(policyBasePremium, contract) + PROCESSING_FEE;
  return { premium: roundPremiumInMhpcoFavor(premium) };
}
/** MHPCO claim settlement: pays out damages against one policy's insured items. */
import type { Item } from "./premium.js";
import { COMPONENT_PRICE, MAIN_ITEM_PRICES, isComponent } from "./priceList.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLIER = 2;

function insuranceValueOf(item: Item): number {
  return isComponent(item.type) ? COMPONENT_PRICE.insuranceValue : MAIN_ITEM_PRICES[item.type].insuranceValue;
}

function insuranceSumOf(items: Item[]): number {
  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
}

/** The total payout per policy is capped at twice the insurance sum. */
function payoutCapOf(policyItems: Item[]): number {
  return CAP_MULTIPLIER * insuranceSumOf(policyItems);
}

function payoutOf(damage: Damage): number {
  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
}

export function claim(policyItems: Item[], damages: Damage[]): ClaimResult {
  const payout = damages.reduce((sum, damage) => sum + payoutOf(damage), 0);
  return { payout, remainingCap: payoutCapOf(policyItems) - payout };
}
/** MHPCO price list: insurance value and base premium of every insurable item type. */

export interface ItemPrice {
  insuranceValue: number;
  basePremium: number;
}

export const MAIN_ITEM_PRICES: Record<string, ItemPrice> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
};

/** Components are priced and insured per piece; a block of alike components has a special base premium. */
export const COMPONENT_PRICE: ItemPrice = { insuranceValue: 250, basePremium: 25 };
export const COMPONENT_BLOCK_SIZE = 3;
export const COMPONENT_BLOCK_BASE_PREMIUM = 60;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

/** Components (runes, moonstones, ...) are priced and insured per piece rather than as main items. */
export function isComponent(type: string): boolean {
  return COMPONENT_TYPES.has(type);
}
